"""Generated by ANG. Run only through the project's private Blender wrapper."""
import argparse
import json
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
from runtime import digest, fail, identity_tags, import_asset, model_matrix, signature, write_json
import bpy
from mathutils import Matrix, Vector

parser = argparse.ArgumentParser()
parser.add_argument('--contract', required=True)
parser.add_argument('--output', required=True)
parser.add_argument('--render')
parser.add_argument('--handover', action='store_true', help='omit CUE-derived preview art so Blender-first edits can recompute it from the new floor')
parser.add_argument('--kits-only', action='store_true', help='one copy of each mapped reusable kit input for migration checks')
args = parser.parse_args(sys.argv[sys.argv.index('--') + 1:])
contract = json.loads(Path(args.contract).read_text())
output = Path(args.output).resolve()
if output.exists() or output.suffix != '.blend':
    fail(f'{output}: starting file must be a NEW .blend; choose a new output path')
bpy.ops.wm.read_factory_settings(use_empty=True)
scene = bpy.context.scene
scene.unit_settings.system = 'METRIC'
scene.unit_settings.scale_length = 1
scene['ang_contract_sha256'] = digest(args.contract)
scene['ang_structural_hash'] = contract['structural_hash']
b2g = Matrix(contract['convention']['blender_to_world'])
g2b = b2g.inverted()
kinds = {}
sources = {}
for key, row in sorted(contract['identities'].items()):
    if args.handover and row.get('derived'):
        continue
    if args.kits_only:
        if row['kind'] != 'kit' or key != row['model_ref'] or not row['asset']:
            continue

    kind = row['kind']
    if kind not in kinds:
        col = bpy.data.collections.new('COL_' + kind)
        scene.collection.children.link(col)
        kinds[kind] = col
    col = bpy.data.collections.new('COL_' + key)
    kinds[kind].children.link(col)
    col['ang_id'] = key
    if row.get('module_id'):
        col['ang_module'] = row['module_id']
    col['ang_cue_pose'] = json.dumps(row['world'])
    col['ang_lod'] = 0
    col['ang_library'] = not row['required'] and not args.kits_only
    col['ang_derived'] = row.get('derived',False)
    if row.get('floor'):
        col['ang_floor']=True
    if row.get('layer'):
        col['ang_layer']=row['layer']
    if row.get('material_role'):
        col['ang_material_role'] = row['material_role']
    if row.get('rendered_by'):
        col['ang_rendered_by']=row['rendered_by']
    asset_path = row.get('source_asset') or row.get('asset')
    asset = Path(asset_path) if asset_path else None
    if asset and asset.is_file() and not row['greybox'] and not (row.get('rendered_by') and not row.get('model_ref')) and not col['ang_library']:
        sources[key], _ = import_asset(scene, contract, key, str(asset), collection=col)
    else:
        boxes = [] if col['ang_library'] or (row.get('rendered_by') and not row.get('model_ref')) else row['blockout'] if row['greybox'] else row['blockout'] or [{'center_blender_m': list(g2b @ Matrix(row['world']).translation), 'size_blender_m': [.5, .5, .5]}]
        for index, box in enumerate(boxes):
            bpy.ops.mesh.primitive_cube_add(size=1, location=box['center_blender_m'])
            obj = bpy.context.object
            obj.name = key + ':blockout:' + str(index)
            obj.scale = box['size_blender_m']
            bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
            obj['ang_placeholder'] = not row['greybox'] and not row.get('procedural')
            if row.get('procedural'):
                if row['kind']=='floor':
                    obj['ang_floor']=True
                elif row['kind']=='procedural_wall':
                    obj['ang_wall']=True
                obj['ang_material_role'] = row['material_role']
            for owner in list(obj.users_collection):
                owner.objects.unlink(obj)
            col.objects.link(obj)
    # A non-rendering pose datum remains at the exact CUE pivot while geometry
    # may be replaced. Its name is descriptive; export selects only the tag.
    datum = bpy.data.objects.new('CUE:' + key, None)
    col.objects.link(datum)
    datum.matrix_world = g2b @ Matrix(row['world']) @ Matrix(contract['convention']['model_reflection']) @ b2g
    datum.empty_display_size = .25
    datum['ang_pose_datum'] = True
locators = bpy.data.collections.new('COL_locators')
scene.collection.children.link(locators)
for row in contract['locators']:
    obj = bpy.data.objects.new(row['name'], None)
    locators.objects.link(obj)
    obj['ang_locator'] = row['name']
    obj['ang_id'] = row['instance_id']
    x, z, y = row['position_plan_m']
    obj.location = (x, y, z)
    obj.empty_display_type = 'ARROWS'
    obj.empty_display_size = .3
scene['ang_source_assets'] = json.dumps(sources)
camera = bpy.data.cameras.new('ANG_GameCamera')
obj = bpy.data.objects.new('ANG_GameCamera', camera)
scene.collection.objects.link(obj)
obj.matrix_world = g2b @ Matrix(contract['camera_world'])
camera.type = 'ORTHO'
camera.ortho_scale = contract['frame_m'] * 1280 / 800  # Blender fits width; Godot size is vertical.
scene.camera = obj
for index, position in enumerate([(15, -10, 25), (-5, 20, 20)]):
    light = bpy.data.lights.new('ANG_PreviewFill' + str(index), 'AREA')
    light.energy = 2200
    light.shape = 'DISK'
    light.size = 16
    ob = bpy.data.objects.new(light.name, light)
    scene.collection.objects.link(ob)
    focus = g2b @ (Matrix(contract['camera_world']).translation - Matrix(contract['camera_world']).to_3x3().col[2] * 120)
    ob.location = focus + Vector(position)
    ob.rotation_euler = (focus - ob.location).to_track_quat('-Z', 'Y').to_euler()
    ob['ang_preview_only'] = True
scene.world = bpy.data.worlds.new('ANG_PreviewWorld')
scene.world.color = (.16, .16, .16)
scene.render.engine = 'BLENDER_EEVEE'
scene.render.resolution_x = 1280
scene.render.resolution_y = 800
scene.render.resolution_percentage = 100
identity_tags(scene, contract['identities'])
output.parent.mkdir(parents=True, exist_ok=True)
bpy.ops.wm.save_as_mainfile(filepath=str(output))
write_json(output.with_suffix('.starting.json'), {'schema': 'ang.blender-start.v1', 'contract_sha256': digest(args.contract), 'blend_sha256': digest(output), 'identities': len(identity_tags(scene, contract['identities'])[0]), 'camera_frame_m': contract['frame_m'], 'sources': sources, 'module_tags': {col['ang_id']:col['ang_module'] for col in bpy.data.collections if col.get('ang_id') and col.get('ang_module')}})
if args.render:
    scene.render.filepath = str(Path(args.render).resolve())
    bpy.ops.render.render(write_still=True)
print('ANG_BLENDER_START_PASS', str(output))
